def get_app_root() -> Path:
    if getattr(sys, "frozen", False):
        cand = Path(sys.executable).resolve().parent
    else:
        this_path = Path(__file__).resolve()
        if this_path.name == "__main__.py" and this_path.parent.suffix.lower() == ".exe":
            cand = this_path.parent.parent
        else:
            cand = this_path.parent

    if (cand / "download").is_dir() and (cand / "summarize").is_dir():
        return cand
    if (cand.parent / "download").is_dir() and (cand.parent / "summarize").is_dir():
        return cand.parent
    if (cand / "toolkit" / "download").is_dir() and (cand / "toolkit" / "summarize").is_dir():
        return cand / "toolkit"
    return cand


