def ensure_core_scripts(root: Path = ROOT_DIR, force_upgrade: bool = False):
    upgraded_keys = {"一键安装环境依赖.ps1", "download/douyin.js", "xhs/xhs.js", "summarize/pipeline.py", "summarize/batch_platform.py"}
    for rel_path, b64_data in EMBEDDED_SCRIPTS.items():
        target = root / rel_path
        # 对 llm_config.txt：若已存在则绝不覆盖，若不存在且有 sample 则不动
        if rel_path == "summarize/llm_config.txt" and target.exists():
            continue
        if not target.exists() or (force_upgrade and rel_path in upgraded_keys):
            try:
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(base64.b64decode(b64_data))
            except Exception:
                pass


def reveal_in_explorer(target_path: Path, select_file: bool = True):
    """在 Windows 资源管理器中定位并高亮选中指定文件，或打开其所在目录"""
    p = target_path.resolve()
    if os.name == "nt":
        if select_file and p.is_file():
            subprocess.Popen(["explorer.exe", f"/select,{str(p)}"])
        else:
            folder = p if p.is_dir() else p.parent
            folder.mkdir(parents=True, exist_ok=True)
            os.startfile(str(folder))
    else:
        folder = p if p.is_dir() else p.parent
        subprocess.Popen(["xdg-open", str(folder)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def open_file_default(target_path: Path):
    """使用操作系统默认程序打开指定文件"""
    p = target_path.resolve()
    if not p.exists():
        return
    if os.name == "nt":
        os.startfile(str(p))
    else:
        subprocess.Popen(["xdg-open", str(p)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


