class RuntimeEnv:
    def __init__(self, root: Path = ROOT_DIR):
        self.root = root
        ensure_core_scripts(self.root, force_upgrade=True)
        self.localappdata = Path(os.environ.get("LOCALAPPDATA") or (Path.home() / "AppData" / "Local"))
        self.appdata = Path(os.environ.get("APPDATA") or (Path.home() / "AppData" / "Roaming"))
        self.userprofile = Path(os.environ.get("USERPROFILE") or Path.home())
        self.programfiles = Path(os.environ.get("ProgramFiles") or r"C:\Program Files")
        self.programfiles_x86 = Path(os.environ.get("ProgramFiles(x86)") or r"C:\Program Files (x86)")

        self.ytdlp_dir = self.localappdata / "Programs" / "yt-dlp"
        self.ytdlp_exe = self._find_bin("yt-dlp", [self.ytdlp_dir / "yt-dlp.exe"])

        self.ffmpeg_dir = self.localappdata / "Programs" / "ffmpeg" / "bin"
        self.ffmpeg_exe = self._find_bin("ffmpeg", [
            self.ffmpeg_dir / "ffmpeg.exe",
            self.programfiles / "ffmpeg" / "bin" / "ffmpeg.exe",
        ])

        self.deno_dir = self.localappdata / "Programs" / "deno"
        self.deno_exe = self._find_bin("deno", [self.deno_dir / "deno.exe"])

        self.pot_plugin_dir = self.appdata / "yt-dlp" / "plugins"
        self.pot_server_dir = self.userprofile / "bgutil-ytdlp-pot-provider"
        self.pot_main_js = self.pot_server_dir / "server" / "build" / "main.js"

        self.whisper_venv = self.localappdata / "Programs" / "whisper" / "venv"
        self.whisper_py = self._find_bin("python3", [
            self.whisper_venv / "Scripts" / "python.exe",
            self.whisper_venv / "bin" / "python",
        ])
        self.whisper_cache = self.userprofile / ".cache" / "whisper"

        self.scrapling_venv = self.localappdata / "Programs" / "scrapling" / "venv"
        self.scrapling_py = self._find_bin("python3", [
            self.scrapling_venv / "Scripts" / "python.exe",
            self.scrapling_venv / "bin" / "python",
        ])
        self.scrapling_exe = self._find_bin("scrapling", [
            self.scrapling_venv / "Scripts" / "scrapling.exe",
            self.scrapling_venv / "bin" / "scrapling",
        ])

        self.ms_playwright = self.localappdata / "ms-playwright"
        self.node_dir = self.programfiles / "nodejs"
        self.node_exe = self._find_bin("node", [self.node_dir / "node.exe"])

        self.firefox_exe = self._find_bin("firefox", [
            self.programfiles / "Mozilla Firefox" / "firefox.exe",
            self.programfiles_x86 / "Mozilla Firefox" / "firefox.exe",
        ])
        self.firefox_profiles = self.appdata / "Mozilla" / "Firefox" / "Profiles"

    @staticmethod
    def _find_bin(name: str, candidates: list[Path]) -> str:
        for c in candidates:
            if c.exists():
                return str(c)
        found = shutil.which(name)
        return found or str(candidates[0])

    def build_env(self, extra_env: dict | None = None) -> dict:
        env = os.environ.copy()
        prepend_dirs = [
            str(self.ytdlp_dir),
            str(self.ffmpeg_dir),
            str(self.deno_dir),
            str(self.node_dir),
        ]
        existing_path = env.get("PATH", "")
        env["PATH"] = os.pathsep.join(prepend_dirs) + os.pathsep + existing_path
        env["PYTHONIOENCODING"] = "utf-8"
        env["PYTHONUTF8"] = "1"
        if extra_env:
            env.update(extra_env)
        return env

    def get_download_out_dir(self) -> Path:
        if os.environ.get("YTDLP_OUT"):
            return Path(os.environ["YTDLP_OUT"])
        out_txt = self.root / "download" / "OUT.txt"
        if out_txt.exists():
            try:
                lines = [x.strip() for x in out_txt.read_text(encoding="utf-8", errors="ignore").splitlines() if x.strip()]
                if lines:
                    return Path(lines[0])
            except Exception:
                pass
        return self.userprofile / "Videos" / "yt-dlp"

    def set_download_out_dir(self, new_dir: str) -> Path:
        p = Path(new_dir.strip())
        p.mkdir(parents=True, exist_ok=True)
        out_txt = self.root / "download" / "OUT.txt"
        out_txt.parent.mkdir(parents=True, exist_ok=True)
        out_txt.write_text(str(p) + "\n", encoding="utf-8")
        return p

    def get_xhs_out_dir(self) -> Path:
        if os.environ.get("XHS_OUT"):
            return Path(os.environ["XHS_OUT"])
        out_txt = self.root / "xhs" / "OUT.txt"
        if out_txt.exists():
            try:
                lines = [x.strip() for x in out_txt.read_text(encoding="utf-8", errors="ignore").splitlines() if x.strip()]
                if lines:
                    return Path(lines[0])
            except Exception:
                pass
        return self.userprofile / "Pictures" / "xhs"

    def get_llm_config(self) -> dict:
        cfg = {"KEY": "", "BASE": "https://api.deepseek.com/v1", "MODEL": "deepseek-chat"}
        cfg_file = self.root / "summarize" / "llm_config.txt"
        if cfg_file.exists():
            for line in cfg_file.read_text(encoding="utf-8", errors="ignore").splitlines():
                line = line.strip()
                if not line or line.startswith("#") or "=" not in line:
                    continue
                k, v = line.split("=", 1)
                cfg[k.strip().upper()] = v.strip().strip('"').strip("'")
        return cfg

    def save_llm_config(self, key: str, base: str, model: str):
        cfg_file = self.root / "summarize" / "llm_config.txt"
        cfg_file.parent.mkdir(parents=True, exist_ok=True)
        content = f"KEY={key.strip()}\nBASE={base.strip()}\nMODEL={model.strip()}\n"
        cfg_file.write_text(content, encoding="utf-8")

    def get_quick_status(self) -> dict:
        cookie_dbs = list(self.firefox_profiles.glob("*/cookies.sqlite")) if self.firefox_profiles.exists() else []
        return {
            "pot_running": self.is_pot_server_running(),
            "firefox_profiles": len(cookie_dbs),
        }

    def list_recent_artifacts(self, limit: int = 30) -> list[dict]:
        candidates: list[tuple[float, str, Path]] = []
        sum_out = self.root / "summarize" / "out"
        if sum_out.exists():
            for p in sum_out.rglob("*"):
                if p.is_file() and p.suffix.lower() in (".md", ".srt", ".txt") and not p.name.startswith("temp_"):
                    candidates.append((p.stat().st_mtime, "summarize", p))
        scp_out = self.root / "scrape" / "output"
        if scp_out.exists():
            for p in scp_out.rglob("*"):
                if p.is_file() and p.suffix.lower() in (".md", ".csv", ".txt", ".json"):
                    candidates.append((p.stat().st_mtime, "scrape", p))
        xhs_out = self.get_xhs_out_dir()
        if xhs_out.exists():
            for p in xhs_out.rglob("笔记.txt"):
                if p.is_file():
                    candidates.append((p.stat().st_mtime, "xhs", p))

        candidates.sort(key=lambda x: -x[0])
        result = []
        for mtime, subsys, p in candidates[:limit]:
            display_name = p.name if p.name != "笔记.txt" else f"{p.parent.name}/笔记.txt"
            result.append({
                "name": display_name,
                "subsys": subsys,
                "path": str(p),
                "size_kb": round(p.stat().st_size / 1024, 1),
                "mtime": time.strftime("%m-%d %H:%M", time.localtime(mtime)),
            })
        return result

    def inspect_all_dependencies(self) -> list[dict]:
        items = []

        def check_cmd(exe_path: str, args: list[str], timeout: int = 12) -> tuple[bool, str]:
            p = Path(exe_path)
            if not p.exists() and not shutil.which(exe_path):
                return False, f"未找到 ({exe_path})"
            try:
                r = subprocess.run(
                    [exe_path, *args],
                    capture_output=True,
                    timeout=timeout, env=self.build_env()
                )
                out_str = decode_console_line(r.stdout or b"") + "\n" + decode_console_line(r.stderr or b"")
                lines = [ln.strip() for ln in out_str.splitlines() if ln.strip()]
                if r.returncode == 0:
                    return True, (lines[0][:75] if lines else "可用")
                err_msg = lines[-1][:75] if lines else f"退出码 {r.returncode}"
                return False, err_msg
            except Exception as e:
                return False, str(e)[:65]

        ok, ver = check_cmd(self.ytdlp_exe, ["--version"])
        items.append({"name": "yt-dlp", "expected": "2026.10.26", "path": str(self.ytdlp_dir / "yt-dlp.exe"), "used_by": "download / summarize", "ok": ok, "detail": ver})

        ok, ver = check_cmd(self.ffmpeg_exe, ["-version"])
        items.append({"name": "ffmpeg / ffprobe", "expected": "9.0.2", "path": str(self.ffmpeg_dir), "used_by": "download / summarize", "ok": ok, "detail": ver})

        ok, ver = check_cmd(self.deno_exe, ["--version"])
        items.append({"name": "deno", "expected": "2.9.8", "path": str(self.deno_dir), "used_by": "YouTube JS 挑战", "ok": ok, "detail": ver})

        pot_exists = self.pot_main_js.exists()
        pot_listening = self.is_pot_server_running()
        items.append({"name": "POT 插件 + 服务端", "expected": "bgutil 2.0.2", "path": str(self.pot_server_dir), "used_by": "YouTube 媒体流 (:4416)", "ok": pot_exists, "detail": f"服务端脚本{'存在' if pot_exists else '未找到'} · 端口 4416: {'运行中' if pot_listening else '未启动'}"})

        whisper_venv_py = self.whisper_venv / "Scripts" / "python.exe"
        ok, ver = check_cmd(
            str(whisper_venv_py) if whisper_venv_py.exists() else self.whisper_py,
            ["-c", "import sys, whisper, torch; print(f'Py {sys.version.split()[0]} · whisper {whisper.__version__} · torch {torch.__version__}')"],
            timeout=20
        )
        models = [p.name for p in self.whisper_cache.glob("*.pt")] if self.whisper_cache.exists() else []
        items.append({"name": "Python 3.12 venv (Whisper)", "expected": "whisper 20250625 / torch 2.15", "path": str(self.whisper_venv), "used_by": "summarize", "ok": ok, "detail": f"{ver} · 缓存: {', '.join(models) if models else '无'}"})

        scrapling_venv_py = self.scrapling_venv / "Scripts" / "python.exe"
        ok, ver = check_cmd(
            str(scrapling_venv_py) if scrapling_venv_py.exists() else self.scrapling_py,
            ["-c", "import sys, scrapling, curl_cffi; print(f'Py {sys.version.split()[0]} · scrapling {scrapling.__version__} · curl_cffi {curl_cffi.__version__}')"],
            timeout=15
        )
        items.append({"name": "Python 3.14 venv (Scrapling)", "expected": "scrapling 0.5.1", "path": str(self.scrapling_venv), "used_by": "scrape", "ok": ok, "detail": ver})

        c1248 = (self.ms_playwright / "chromium-1248").exists()
        c1255 = (self.ms_playwright / "chromium-1255").exists()
        items.append({"name": "浏览器内核 (ms-playwright)", "expected": "chromium 1248 / 1255", "path": str(self.ms_playwright), "used_by": "scrape 浏览器模式", "ok": c1248 or c1255, "detail": f"chromium-1248: {'已装' if c1248 else '未装'} · chromium-1255: {'已装' if c1255 else '未装'}"})

        ok, ver = check_cmd(self.node_exe, ["--version"])
        items.append({"name": "Node.js", "expected": "24.15.0 (含 node:sqlite)", "path": str(self.node_exe), "used_by": "douyin.js / xhs.js / POT", "ok": ok, "detail": ver})

        ff_ok = Path(self.firefox_exe).exists() or bool(shutil.which("firefox"))
        cookie_dbs = list(self.firefox_profiles.glob("*/cookies.sqlite")) if self.firefox_profiles.exists() else []
        items.append({"name": "Firefox 实时登录态", "expected": "Firefox 160+", "path": str(self.firefox_exe), "used_by": "YouTube / 小红书 / 抖音 / B站", "ok": ff_ok or len(cookie_dbs) > 0, "detail": f"程序: {'存在' if ff_ok else '未找到'} · Profile 库: {len(cookie_dbs)} 个"})

        return items

    @staticmethod
    def is_pot_server_running() -> bool:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.settimeout(0.4)
            return s.connect_ex(("127.0.0.1", 4416)) == 0

    def start_pot_server(self, log_fn=print) -> bool:
        if self.is_pot_server_running():
            log_fn("[POT] 服务端已在 127.0.0.1:4416 运行中")
            return True
        if not self.pot_main_js.exists():
            log_fn(f"[POT] 未找到服务端构建文件: {self.pot_main_js}")
            return False
        log_fn(f"[POT] 正在后台启动服务: {self.pot_main_js}")
        kwargs = {"env": self.build_env(), "stdout": subprocess.DEVNULL, "stderr": subprocess.DEVNULL}
        if os.name == "nt":
            kwargs["creationflags"] = subprocess.CREATE_NO_WINDOW | subprocess.DETACHED_PROCESS
        subprocess.Popen([self.node_exe, str(self.pot_main_js)], **kwargs)
        for _ in range(8):
            time.sleep(0.5)
            if self.is_pot_server_running():
                log_fn("[POT] 启动成功，正在监听 127.0.0.1:4416")
                return True
        log_fn("[POT] 启动超时，请检查 Node.js 与端口状态")
        return False


