# 2. 任务执行器
# ==============================================================================

class TaskRunner:
    def __init__(self, rt: RuntimeEnv, log_callback=print):
        self.rt = rt
        self.log = log_callback
        self.current_proc: subprocess.Popen | None = None
        self._stop_requested = False

    def stop(self):
        self._stop_requested = True
        if self.current_proc and self.current_proc.poll() is None:
            pid = self.current_proc.pid
            try:
                if os.name == "nt":
                    # v3.1：Windows 下 taskkill /F /T 杀整棵进程树，否则 yt-dlp/ffmpeg
                    # 等子进程会变成孤儿进程继续占用网络与文件句柄。
                    subprocess.run(["taskkill", "/F", "/T", "/PID", str(pid)],
                                   stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=10)
                else:
                    self.current_proc.terminate()
                self.log("\n[系统] 已发送终止信号，正在停止当前任务（含子进程）...")
            except Exception:
                try:
                    self.current_proc.terminate()
                except Exception:
                    pass
                self.log("\n[系统] 终止进程异常，已尝试 terminate 兜底")

    def run_cmd(self, cmd: list[str], cwd: Path | None = None, extra_env: dict | None = None) -> int:
        self._stop_requested = False
        env = self.rt.build_env(extra_env)

        if cmd and "yt-dlp" in Path(str(cmd[0])).name.lower() and "--encoding" not in cmd:
            cmd = [cmd[0], "--encoding", "utf-8", *cmd[1:]]

        cmd_str = " ".join(f'"{c}"' if " " in str(c) else str(c) for c in cmd)
        self.log(f"\n$ {cmd_str}")
        if cwd:
            self.log(f"  cwd: {cwd}")

        kwargs = {
            "cwd": str(cwd) if cwd else None,
            "env": env,
            "stdout": subprocess.PIPE,
            "stderr": subprocess.STDOUT,
        }
        if os.name == "nt":
            kwargs["creationflags"] = subprocess.CREATE_NO_WINDOW

        try:
            self.current_proc = subprocess.Popen(cmd, **kwargs)
            assert self.current_proc.stdout is not None
            for raw_line in iter(self.current_proc.stdout.readline, b""):
                if self._stop_requested:
                    break
                line = decode_console_line(raw_line).rstrip("\r\n")
                self.log(line)
            rc = self.current_proc.wait()
        except FileNotFoundError as e:
            self.log(f"[错误] 找不到可执行程序: {cmd[0]} ({e})")
            return 1
        except Exception as e:
            self.log(f"[错误] 执行异常: {e}")
            return 1
        finally:
            self.current_proc = None

        self._explain_exit_code(rc)
        return rc

    def _explain_exit_code(self, rc: int):
        if rc == 0:
            self.log("\n[完成] 退出码 0 (执行成功)")
        elif rc == 3:
            self.log("\n[风控提示] 退出码 3：触发平台验证页或 412 限制，请暂停 3~10 分钟后再试，避免并发请求")
        elif rc == 4:
            self.log("\n[登录提示] 退出码 4：未检测到登录态，请先在 Firefox 浏览器中登录对应站点后重试")
        else:
            self.log(f"\n[结束] 退出码: {rc}")

    def run_download(
        self,
        mode: str,
        target: str,
        out_dir: str | None = None,
        cookie_mode: str = "firefox",
        count: int = 5,
        max_minutes: int = 0,
        yt_list_only: bool = False,
    ) -> int:
        out_path = Path(out_dir) if out_dir else self.rt.get_download_out_dir()
        out_path.mkdir(parents=True, exist_ok=True)
        cookies_txt = DOWNLOAD_DIR / "cookies.txt"

        ck_args = []
        if cookie_mode == "firefox":
            ck_args = ["--cookies-from-browser", "firefox"]
        elif cookie_mode == "chrome":
            ck_args = ["--cookies-from-browser", "chrome"]
        elif cookie_mode == "edge":
            ck_args = ["--cookies-from-browser", "edge"]
        elif cookie_mode == "file" and cookies_txt.exists():
            ck_args = ["--cookies", str(cookies_txt)]

        if mode == "douyin":
            douyin_js = DOWNLOAD_DIR / "douyin.js"
            urls = [u.strip() for u in target.splitlines() if u.strip() and not u.strip().startswith("#")]
            last_rc = 0
            for idx, u in enumerate(urls):
                if self._stop_requested:
                    break
                if idx > 0:
                    self.log("  [串行防风控] 间隔等待 2 秒...")
                    time.sleep(2)
                rc = self.run_cmd([self.rt.node_exe, str(douyin_js), u, str(out_path)], cwd=DOWNLOAD_DIR)
                if rc == 3 and not self._stop_requested:
                    self.log("  [风控退避] 等待 180 秒后自动重试一次...")
                    for _ in range(180):
                        if self._stop_requested:
                            return 3
                        time.sleep(1)
                    rc = self.run_cmd([self.rt.node_exe, str(douyin_js), u, str(out_path)], cwd=DOWNLOAD_DIR)
                last_rc = rc
            return last_rc

        if mode == "yt_search":
            if self.rt.pot_main_js.exists() and not self.rt.is_pot_server_running():
                self.rt.start_pot_server(self.log)
            secs = max_minutes * 60 if max_minutes and max_minutes > 0 else 999999999
            archive_file = DOWNLOAD_DIR / "downloaded-youtube.txt"
            if yt_list_only:
                cmd = [
                    self.rt.ytdlp_exe, "--flat-playlist", "--no-warnings",
                    f"ytsearch{count}:{target}",
                    "--print", "%(title)s | %(id)s | %(duration_string)s",
                    "--match-filter", f"duration < {secs}",
                    *ck_args,
                ]
                return self.run_cmd(cmd, cwd=DOWNLOAD_DIR)

            cmd = [
                self.rt.ytdlp_exe, f"ytsearch{count}:{target}",
                "--yes-playlist", "-I", f"1:{count}",
                "-P", str(out_path),
                "-o", r"%(uploader,channel|Unknown)s\%(upload_date>%Y-%m-%d)s - %(title)s [%(id)s].%(ext)s",
                "-f", "bv*+ba/b", "-S", "res:1080",
                "--merge-output-format", "mp4",
                "--embed-metadata", "--write-thumbnail", "--convert-thumbnails", "jpg",
                "--windows-filenames", "--download-archive", str(archive_file),
                "--match-filter", f"duration < {secs}",
                "--ignore-errors", "--sleep-requests", "1",
                "--retries", "10", "--fragment-retries", "10", "-N", "8",
                *ck_args,
            ]
            rc = self.run_cmd(cmd, cwd=DOWNLOAD_DIR)
            if rc != 0 and not self._stop_requested:
                self.log("\n[回退] 尝试 360p/480p 免流鉴权格式...")
                cmd_fallback = [
                    self.rt.ytdlp_exe, f"ytsearch{count}:{target}",
                    "--yes-playlist", "-I", f"1:{count}",
                    "-P", str(out_path),
                    "-o", r"%(uploader,channel|Unknown)s\%(upload_date>%Y-%m-%d)s - %(title)s [%(id)s].%(ext)s",
                    "-f", "18/b[height<=480]",
                    "--merge-output-format", "mp4",
                    "--embed-metadata", "--windows-filenames",
                    "--download-archive", str(archive_file),
                    "--match-filter", f"duration < {secs}",
                    "--ignore-errors", "--sleep-requests", "1",
                    "--retries", "5", "--fragment-retries", "5",
                    *ck_args,
                ]
                rc = self.run_cmd(cmd_fallback, cwd=DOWNLOAD_DIR)
            return rc

        urls = [u.strip() for u in target.splitlines() if u.strip() and not u.strip().startswith("#")]
        last_rc = 0
        for u in urls:
            if self._stop_requested:
                break
            if mode == "1080p":
                cmd = [
                    self.rt.ytdlp_exe, "-P", str(out_path),
                    "-o", r"%(uploader,channel,creator|Unknown)s\%(upload_date>%Y-%m-%d)s - %(title)s [%(id)s].%(ext)s",
                    "-f", "bv*+ba/b", "-S", "res:1080,vcodec:h264,acodec:aac",
                    "--merge-output-format", "mp4", "--no-playlist",
                    "--embed-metadata", "--write-thumbnail", "--convert-thumbnails", "jpg",
                    "--windows-filenames", "--retries", "10", "--fragment-retries", "10", "-N", "8",
                    *ck_args, u,
                ]
            elif mode == "subs_cover":
                cmd = [
                    self.rt.ytdlp_exe, "-P", str(out_path),
                    "-o", r"%(uploader,channel,creator|Unknown)s\%(upload_date>%Y-%m-%d)s - %(title)s [%(id)s].%(ext)s",
                    "-f", "bv*+ba/b", "-S", "res:1080,vcodec:h264,acodec:aac",
                    "--merge-output-format", "mp4", "--no-playlist",
                    "--write-subs", "--write-auto-subs", "--sub-langs", "zh.*,ai-zh,en.*",  # v3.1：补 B站 ai-zh
                    "--embed-subs", "--convert-subs", "srt",
                    "--embed-metadata", "--write-thumbnail", "--convert-thumbnails", "jpg",
                    "--windows-filenames", "--retries", "10", "--fragment-retries", "10", "-N", "8",
                    *ck_args, u,
                ]
            elif mode == "mp3":
                cmd = [
                    self.rt.ytdlp_exe, "-P", str(out_path),
                    "-o", r"%(uploader,channel,creator|Unknown)s\%(title)s [%(id)s].%(ext)s",
                    "-f", "ba/b", "-x", "--audio-format", "mp3", "--audio-quality", "0",
                    "--embed-thumbnail", "--embed-metadata", "--no-playlist",
                    "--windows-filenames", "--retries", "10", "--fragment-retries", "10", "-N", "8",
                    *ck_args, u,
                ]
            elif mode == "playlist":
                archive_file = out_path / "archive.txt"
                cmd = [
                    self.rt.ytdlp_exe, "-P", str(out_path),
                    "-o", r"%(playlist_title,channel,uploader|Playlist)s\%(playlist_index)03d - %(title)s [%(id)s].%(ext)s",
                    "-f", "bv*+ba/b", "-S", "res:1080,vcodec:h264,acodec:aac",
                    "--merge-output-format", "mp4", "--yes-playlist",
                    "--download-archive", str(archive_file),
                    "--ignore-errors", "--embed-metadata", "--windows-filenames",
                    "--retries", "10", "--fragment-retries", "10", "--sleep-requests", "1", "-N", "8",
                    *ck_args, u,
                ]
            elif mode == "formats":
                cmd = [self.rt.ytdlp_exe, "-F", *ck_args, u]
            else:
                cmd = [self.rt.ytdlp_exe, "-P", str(out_path), *ck_args, u]

            last_rc = self.run_cmd(cmd, cwd=DOWNLOAD_DIR)
        return last_rc

    def merge_cookies(self) -> int:
        merge_js = DOWNLOAD_DIR / "merge-cookies.js"
        src_dir = DOWNLOAD_DIR / "cookies-src"
        out_cookie = DOWNLOAD_DIR / "cookies.txt"
        return self.run_cmd([self.rt.node_exe, str(merge_js), str(src_dir), str(out_cookie)], cwd=DOWNLOAD_DIR)

    def test_youtube_cookies(self, use_firefox: bool = True) -> int:
        args = ["--cookies-from-browser", "firefox"] if use_firefox else ["--cookies", str(DOWNLOAD_DIR / "cookies.txt")]
        cmd = [
            self.rt.ytdlp_exe, *args, "--simulate", "--no-warnings",
            "--print", "[PASS] 登录态有效，成功解析视频标题: %(title).50s",
            "https://www.youtube.com/watch?v=9bZkp7q19f0",
        ]
        return self.run_cmd(cmd, cwd=DOWNLOAD_DIR)

    def set_global_firefox_cookie(self, enable: bool = True) -> str:
        cfg_dir = self.rt.appdata / "yt-dlp"
        cfg_dir.mkdir(parents=True, exist_ok=True)
        cfg_file = cfg_dir / "config"
        line = "--cookies-from-browser firefox"
        if enable:
            existing = cfg_file.read_text(encoding="utf-8", errors="ignore") if cfg_file.exists() else ""
            if "cookies-from-browser" not in existing:
                with open(cfg_file, "a", encoding="utf-8") as f:
                    f.write(f"\n{line}\n")
                return f"已启用全局 Firefox 实时 Cookie: {cfg_file}"
            return f"全局配置已包含 cookies-from-browser: {cfg_file}"
        else:
            if cfg_file.exists():
                cfg_file.unlink()
                return f"已移除 yt-dlp 全局配置: {cfg_file}"
            return "当前无全局配置文件"

    def run_summarize_single(
        self,
        target: str,
        summary_mode: str = "ai",
        model: str = "small",
        language: str = "zh",
        out_dir: str | None = None,
        keep_audio: bool = False,
        cookie_browser: str = "firefox",
        force_asr: bool = False,
    ) -> int:
        pipeline_py = SUMMARIZE_DIR / "pipeline.py"
        cmd = [self.rt.whisper_py, str(pipeline_py), target.strip(), "--model", model]
        if language and language != "auto":
            cmd += ["--language", language]
        if out_dir:
            cmd += ["--out", out_dir]
        if keep_audio:
            cmd.append("--keep-audio")
        if force_asr:
            cmd.append("--force-asr")
        if summary_mode == "local":
            cmd.append("--no-llm")
        elif summary_mode == "transcript_only":
            cmd.append("--no-summary")
        if cookie_browser and cookie_browser != "none":
            cmd += ["--cookies-from-browser", cookie_browser]
        return self.run_cmd(cmd, cwd=SUMMARIZE_DIR)

    def check_llm_config(self) -> int:
        pipeline_py = SUMMARIZE_DIR / "pipeline.py"
        return self.run_cmd([self.rt.whisper_py, str(pipeline_py), "--check-llm", "dummy"], cwd=SUMMARIZE_DIR)

    def run_summarize_batch(
        self,
        mode: str,
        target: str,
        count: int = 3,
        max_duration: int = 600,
        model: str = "small",
        out_dir: str | None = None,
        no_transcribe: bool = False,
    ) -> int:
        batch_py = SUMMARIZE_DIR / "batch_platform.py"
        if mode == "bilibili":
            cmd = [
                self.rt.whisper_py, str(batch_py),
                "bilibili", target.strip(),
                "--count", str(count),
                "--max-duration", str(max_duration),
                "--model", model,
            ]
        else:
            platform = "douyin" if "douyin" in mode else "xhs"
            target_path = Path(target.strip())
            if "\n" in target or not target_path.exists():
                tmp_links = SUMMARIZE_DIR / "out" / f"temp_links_{platform}.txt"
                tmp_links.parent.mkdir(parents=True, exist_ok=True)
                tmp_links.write_text(target.strip() + "\n", encoding="utf-8")
                target_arg = str(tmp_links)
            else:
                target_arg = str(target_path)
            cmd = [
                self.rt.whisper_py, str(batch_py),
                "links", target_arg,
                "--platform", platform,
                "--model", model,
            ]
        if out_dir:
            cmd += ["--out", out_dir]
        if no_transcribe:
            cmd.append("--no-transcribe")
        return self.run_cmd(cmd, cwd=SUMMARIZE_DIR)

    def run_scrape_page(
        self,
        url: str,
        mode: str = "http",
        css_selector: str = "",
        out_file: str | None = None,
    ) -> tuple[int, Path]:
        out_dir = SCRAPE_DIR / "output"
        out_dir.mkdir(parents=True, exist_ok=True)
        out_path = Path(out_file) if out_file else (out_dir / f"page_{int(time.time())}.md")

        if mode == "http":
            cmd = [self.rt.scrapling_exe, "extract", "get", url.strip(), str(out_path)]
        elif mode == "browser":
            cmd = [self.rt.scrapling_exe, "extract", "fetch", url.strip(), str(out_path), "--network-idle"]
        else:
            cmd = [
                self.rt.scrapling_exe, "extract", "fetch", url.strip(), str(out_path),
                "--solve-cloudflare", "--network-idle", "--timeout", "180000"
            ]
        if css_selector.strip():
            cmd += ["--css-selector", css_selector.strip()]

        rc = self.run_cmd(cmd, cwd=SCRAPE_DIR)
        return rc, out_path

    def run_scrape_youtube_search(self, keyword: str, lang: str = "en-US,en;q=0.9", out_csv: str | None = None) -> tuple[int, Path]:
        yt_py = SCRAPE_DIR / "YouTube搜索抓取.py"
        out_dir = SCRAPE_DIR / "output"
        out_dir.mkdir(parents=True, exist_ok=True)
        csv_path = Path(out_csv) if out_csv else (out_dir / f"yt_{int(time.time())}.csv")
        cmd = [self.rt.scrapling_py, str(yt_py), keyword.strip(), "--lang", lang, "--out", str(csv_path)]
        rc = self.run_cmd(cmd, cwd=SCRAPE_DIR)
        return rc, csv_path

    def run_xhs(self, urls_text: str, out_dir: str | None = None) -> int:
        xhs_js = XHS_DIR / "xhs.js"
        out_path = Path(out_dir) if out_dir else self.rt.get_xhs_out_dir()
        out_path.mkdir(parents=True, exist_ok=True)
        urls = [u.strip() for u in urls_text.splitlines() if u.strip() and not u.strip().startswith("#")]
        last_rc = 0
        for idx, u in enumerate(urls):
            if self._stop_requested:
                break
            if idx > 0:
                self.log("  [串行防风控] 间隔等待 2 秒...")
                time.sleep(2)
            rc = self.run_cmd([self.rt.node_exe, str(xhs_js), u, str(out_path)], cwd=XHS_DIR)
            if rc == 3 and not self._stop_requested:
                self.log("  [风控退避] 小红书触发风控，等待 180 秒后自动重试一次...")
                for _ in range(180):
                    if self._stop_requested:
                        return 3
                    time.sleep(1)
                rc = self.run_cmd([self.rt.node_exe, str(xhs_js), u, str(out_path)], cwd=XHS_DIR)
            last_rc = rc
        return last_rc


