class WebStudioState:
    def __init__(self):
        self.rt = RuntimeEnv(ROOT_DIR)
        self.logs: list[str] = [
            f"素材工具包工作台已就绪 · 根目录: {ROOT_DIR}",
            "已加载 4 个子系统与 6 项升级：原生字幕快速通道 / 抖音 Firefox 实时 Cookie / 批量 AI 横向对比 / 小红书图文+视频分流",
        ]
        self.lock = threading.Lock()
        self.runner = TaskRunner(self.rt, log_callback=self.append_log)
        self.running = False
        self.task_name = ""

    def append_log(self, line: str):
        with self.lock:
            self.logs.append(line)
            if len(self.logs) > 4000:
                self.logs = self.logs[-3000:]

    def start_background_task(self, name: str, fn, *args, **kwargs) -> bool:
        if self.running:
            self.append_log("[提示] 当前已有任务正在执行，请等待完成或点击「停止任务」")
            return False
        self.running = True
        self.task_name = name
        self.append_log(f"\n── 开始任务: {name} [{time.strftime('%H:%M:%S')}] ──")

        def worker():
            try:
                fn(*args, **kwargs)
            except Exception as e:
                self.append_log(f"[异常] {e}")
            finally:
                self.running = False

        threading.Thread(target=worker, daemon=True).start()
        return True


def launch_unslop_web_studio():
    state = WebStudioState()
    html_bytes = base64.b64decode(UNSLOP_HTML_B64)

    class StudioHandler(BaseHTTPRequestHandler):
        def log_message(self, format, *args):
            pass

        def _send_json(self, obj: dict, status: int = 200):
            raw = json.dumps(obj, ensure_ascii=False).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(raw)))
            self.end_headers()
            self.wfile.write(raw)

        def do_GET(self):
            parsed = urlparse(self.path)
            if parsed.path in ("/", "/index.html"):
                self.send_response(200)
                self.send_header("Content-Type", "text/html; charset=utf-8")
                self.send_header("Content-Length", str(len(html_bytes)))
                self.end_headers()
                self.wfile.write(html_bytes)
                return

            if parsed.path == "/api/state":
                self._send_json({
                    "root_dir": str(ROOT_DIR),
                    "download_out": str(state.rt.get_download_out_dir()),
                    "xhs_out": str(state.rt.get_xhs_out_dir()),
                    "llm": state.rt.get_llm_config(),
                    "quick_status": state.rt.get_quick_status(),
                })
                return

            if parsed.path == "/api/logs":
                qs = parse_qs(parsed.query)
                since = int(qs.get("since", ["0"])[0])
                with state.lock:
                    slice_lines = state.logs[since:]
                    next_off = len(state.logs)
                self._send_json({
                    "lines": slice_lines,
                    "next_offset": next_off,
                    "running": state.running,
                    "task_name": state.task_name,
                    "quick_status": state.rt.get_quick_status(),
                })
                return

            if parsed.path == "/api/artifacts":
                self._send_json({"files": state.rt.list_recent_artifacts()})
                return

            if parsed.path == "/api/env_check":
                self._send_json({"items": state.rt.inspect_all_dependencies()})
                return

            self.send_error(404)

        def do_POST(self):
            length = int(self.headers.get("Content-Length", "0"))
            body = json.loads(self.rfile.read(length).decode("utf-8")) if length > 0 else {}

            if self.path == "/api/stop":
                state.runner.stop()
                self._send_json({"ok": True})
                return

            if self.path == "/api/save_dl_out":
                p = state.rt.set_download_out_dir(body.get("out_dir", ""))
                state.append_log(f"[配置] 已更新 download/OUT.txt 保存目录: {p}")
                self._send_json({"ok": True, "path": str(p)})
                return

            if self.path == "/api/save_llm":
                state.rt.save_llm_config(body.get("key", ""), body.get("base", ""), body.get("model", ""))
                state.append_log("[配置] 已保存 summarize/llm_config.txt")
                self._send_json({"ok": True})
                return

            if self.path == "/api/open_folder":
                t = body.get("target", "root")
                if t == "download_out":
                    p = Path(body.get("dl_out") or state.rt.get_download_out_dir())
                elif t == "summarize_out":
                    p = SUMMARIZE_DIR / "out"
                elif t == "scrape_out":
                    p = SCRAPE_DIR / "output"
                elif t == "xhs_out":
                    p = Path(body.get("xhs_out") or state.rt.get_xhs_out_dir())
                else:
                    p = ROOT_DIR
                reveal_in_explorer(p, select_file=False)
                self._send_json({"ok": True})
                return

            if self.path == "/api/reveal_file":
                p = Path(body.get("path", ""))
                mode = body.get("mode", "folder")
                if p.exists():
                    if mode == "file":
                        open_file_default(p)
                    else:
                        reveal_in_explorer(p, select_file=True)
                self._send_json({"ok": True})
                return

            if self.path == "/api/read_artifact":
                p = Path(body.get("path", ""))
                content = ""
                if p.exists() and p.is_file():
                    content = p.read_text(encoding="utf-8", errors="replace")[:50000]
                self._send_json({"content": content})
                return

            if self.path == "/api/run":
                act = body.get("action", "")
                if act == "download":
                    state.start_background_task(
                        f"下载 ({body.get('mode')})",
                        state.runner.run_download,
                        body.get("mode", "1080p"),
                        body.get("target", ""),
                        body.get("out_dir") or None,
                        body.get("cookie", "firefox"),
                        int(body.get("count", 5)),
                        int(body.get("max_minutes", 0)),
                    )
                elif act == "pot":
                    state.start_background_task("启动 POT 服务", state.rt.start_pot_server, state.append_log)
                elif act == "install_deps":
                    mode = body.get("mode", "full")
                    ps1 = ROOT_DIR / "一键安装环境依赖.ps1"
                    if not ps1.exists():
                        ensure_core_scripts(ROOT_DIR)
                    if ps1.exists():
                        if os.name == "nt":
                            subprocess.Popen(
                                ["powershell.exe", "-NoProfile", "-NoExit", "-ExecutionPolicy", "Bypass",
                                 "-File", str(ps1), "-Mode", mode],
                                creationflags=subprocess.CREATE_NEW_CONSOLE,
                            )
                            state.append_log(f"[环境] 已在新窗口启动一键安装（{mode} 模式），请在弹出的 PowerShell 窗口中查看进度")
                        else:
                            state.append_log("[环境] 一键安装脚本仅支持 Windows，请在 Windows 上双击 一键安装环境依赖.bat")
                    else:
                        state.append_log("[环境] 未找到 一键安装环境依赖.ps1")
                elif act == "test_cookie":
                    state.start_background_task("验证 YouTube 登录态", state.runner.test_youtube_cookies, bool(body.get("use_firefox", True)))
                elif act == "merge_cookies":
                    state.start_background_task("合并 Cookie 文件", state.runner.merge_cookies)
                elif act == "global_firefox_cookie":
                    msg = state.runner.set_global_firefox_cookie(True)
                    state.append_log("[配置] " + msg)
                elif act == "check_llm":
                    state.start_background_task("测试大模型连通性", state.runner.check_llm_config)
                elif act == "summarize":
                    state.start_background_task(
                        f"转写与总结 ({body.get('model')})",
                        state.runner.run_summarize_single,
                        body.get("target", ""),
                        body.get("summary_mode", "ai"),
                        body.get("model", "small"),
                        body.get("language", "zh"),
                        None,
                        bool(body.get("keep_audio", False)),
                        "firefox",
                        bool(body.get("force_asr", False)),
                    )
                elif act == "batch":
                    state.start_background_task(
                        f"批量分析 ({body.get('mode')})",
                        state.runner.run_summarize_batch,
                        body.get("mode", "bilibili"),
                        body.get("target", ""),
                        int(body.get("count", 3)),
                        int(body.get("max_duration", 600)),
                        body.get("model", "small"),
                    )
                elif act == "scrape_page":
                    state.start_background_task(
                        f"网页抓取 ({body.get('mode')})",
                        state.runner.run_scrape_page,
                        body.get("url", ""),
                        body.get("mode", "http"),
                        body.get("css", ""),
                    )
                elif act == "scrape_yt":
                    state.start_background_task(
                        f"YouTube搜索抓取 ({body.get('keyword')})",
                        state.runner.run_scrape_youtube_search,
                        body.get("keyword", ""),
                    )
                elif act == "xhs":
                    state.start_background_task(
                        "小红书图文/视频下载",
                        state.runner.run_xhs,
                        body.get("urls", ""),
                        body.get("out_dir") or None,
                    )
                self._send_json({"ok": True})
                return

            self.send_error(404)

    server = ThreadingHTTPServer(("127.0.0.1", 0), StudioHandler)
    port = server.server_address[1]
    url = f"http://127.0.0.1:{port}/"
    print("============================================================")
    print(f"  素材工具包 · 工作台已启动: {url}")
    print("  关闭此控制台窗口即可退出服务（也可以加 --tk 参数使用原生 Tkinter 界面）")
    print("============================================================")

    opened_app = False
    if os.name == "nt":
        edge_cands = [
            Path(os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)")) / "Microsoft" / "Edge" / "Application" / "msedge.exe",
            Path(os.environ.get("ProgramFiles", r"C:\Program Files")) / "Microsoft" / "Edge" / "Application" / "msedge.exe",
            Path(os.environ.get("ProgramFiles", r"C:\Program Files")) / "Google" / "Chrome" / "Application" / "chrome.exe",
        ]
        for browser_bin in edge_cands:
            if browser_bin.exists():
                try:
                    subprocess.Popen([str(browser_bin), f"--app={url}", "--window-size=1320,840"])
                    opened_app = True
                    break
                except Exception:
                    pass
    if not opened_app:
        webbrowser.open(url)

    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass


# ==============================================================================
# 4. 原生 Tkinter 备用界面 (同样支持右侧检视器与一键定位所选文件目录)
# ==============================================================================

def launch_tk_gui():
    import tkinter as tk
    from tkinter import ttk

    rt = RuntimeEnv(ROOT_DIR)
    log_queue: queue.Queue[str] = queue.Queue()

    root = tk.Tk()
    root.title(f"素材工具包 · 工作台  ({ROOT_DIR})")
    root.geometry("1260x800")
    root.minsize(1040, 680)

    BG_SIDEBAR = "#0f0f10"
    BG_PAGE = "#141415"
    BG_CARD = "#19191b"
    BG_RAISED = "#232325"
    TEXT_PRI = "#ededed"
    TEXT_SEC = "#a1a1a6"
    TEXT_MUTED = "#85858b"
    ACCENT = "#e56b38"

    root.configure(bg=BG_PAGE)
    style = ttk.Style()
    try:
        style.theme_use("clam")
    except Exception:
        pass

    f_sans = ("Microsoft YaHei UI", 10) if os.name == "nt" else ("Sans", 10)
    f_med = ("Microsoft YaHei UI", 10, "bold") if os.name == "nt" else ("Sans", 10, "bold")
    f_title = ("Microsoft YaHei UI", 12, "bold") if os.name == "nt" else ("Sans", 12, "bold")
    f_mono = ("Consolas", 10) if os.name == "nt" else ("Monospace", 10)

    style.configure(".", font=f_sans, background=BG_PAGE, foreground=TEXT_PRI)
    style.configure("TNotebook", background=BG_PAGE, borderwidth=0)
    style.configure("TNotebook.Tab", font=f_sans, padding=(16, 8), background=BG_SIDEBAR, foreground=TEXT_SEC)
    style.map("TNotebook.Tab", background=[("selected", BG_CARD)], foreground=[("selected", TEXT_PRI)])
    style.configure("Card.TFrame", background=BG_CARD)
    style.configure("Primary.TButton", font=f_med, padding=(14, 6), background=ACCENT, foreground="#ffffff", borderwidth=0)
    style.map("Primary.TButton", background=[("active", "#d45d2b")])
    style.configure("Action.TButton", padding=(10, 5), background=BG_RAISED, foreground=TEXT_PRI, borderwidth=0)
    style.map("Action.TButton", background=[("active", "#2c2c2f")])

    def enqueue_log(msg: str):
        log_queue.put(msg)

    runner = TaskRunner(rt, log_callback=enqueue_log)

    top_bar = tk.Frame(root, bg=BG_SIDEBAR, height=48)
    top_bar.pack(fill="x")
    top_bar.pack_propagate(False)
    tk.Label(top_bar, text="素材工具包 · 工作台", font=f_title, bg=BG_SIDEBAR, fg=TEXT_PRI).pack(side="left", padx=20)
    tk.Label(top_bar, text=str(ROOT_DIR), font=f_mono, bg=BG_SIDEBAR, fg=TEXT_MUTED).pack(side="left", padx=8)
    ttk.Button(top_bar, text="停止当前任务", style="Action.TButton", command=runner.stop).pack(side="right", padx=16, pady=8)

    main_split = ttk.PanedWindow(root, orient="horizontal")
    main_split.pack(fill="both", expand=True, padx=16, pady=12)

    left_paned = ttk.PanedWindow(main_split, orient="vertical")
    right_inspector = tk.Frame(main_split, bg=BG_CARD, width=400)
    main_split.add(left_paned, weight=3)
    main_split.add(right_inspector, weight=2)

    nb = ttk.Notebook(left_paned)
    term_box = tk.Frame(left_paned, bg=BG_SIDEBAR)
    left_paned.add(nb, weight=3)
    left_paned.add(term_box, weight=2)

    # Tab 1: Download
    t_dl = ttk.Frame(nb, style="Card.TFrame", padding=16)
    nb.add(t_dl, text=" 下载中心 ")
    dl_mode = tk.StringVar(value="1080p")
    dl_out = tk.StringVar(value=str(rt.get_download_out_dir()))
    f_m = ttk.Frame(t_dl, style="Card.TFrame")
    f_m.pack(fill="x", pady=4)
    for lbl, val in [("1080p视频", "1080p"), ("视频+字幕+封面", "subs_cover"), ("提取MP3", "mp3"), ("抖音无水印", "douyin"), ("播放列表", "playlist"), ("YouTube关键词搜索", "yt_search")]:
        ttk.Radiobutton(f_m, text=lbl, value=val, variable=dl_mode).pack(side="left", padx=(0, 12))
    dl_txt = tk.Text(t_dl, height=6, font=f_mono, bg=BG_RAISED, fg=TEXT_PRI, insertbackground=TEXT_PRI, relief="flat", padx=8, pady=8)
    dl_txt.pack(fill="both", expand=True, pady=8)
    ttk.Button(t_dl, text="开始执行下载", style="Primary.TButton", command=lambda: threading.Thread(target=runner.run_download, args=(dl_mode.get(), dl_txt.get("1.0", "end").strip(), dl_out.get()), daemon=True).start()).pack(anchor="w")

    # Tab 2: Summarize
    t_sum = ttk.Frame(nb, style="Card.TFrame", padding=16)
    nb.add(t_sum, text=" 转写与总结 ")
    sum_url = tk.StringVar()
    ttk.Label(t_sum, text="视频 URL 或本地文件路径:", background=BG_CARD).pack(anchor="w")
    ttk.Entry(t_sum, textvariable=sum_url, width=80).pack(fill="x", pady=8)
    ttk.Button(t_sum, text="开始转写与总结", style="Primary.TButton", command=lambda: threading.Thread(target=runner.run_summarize_single, args=(sum_url.get(),), daemon=True).start()).pack(anchor="w")

    # Right Inspector
    insp_top = tk.Frame(right_inspector, bg=BG_SIDEBAR, height=40)
    insp_top.pack(fill="x")
    tk.Label(insp_top, text="最近产出检视器", font=f_med, bg=BG_SIDEBAR, fg=TEXT_PRI).pack(side="left", padx=12, pady=8)

    artifact_paths: list[str] = []
    selected_path_var = tk.StringVar(value="")

    listbox = tk.Listbox(right_inspector, height=8, bg=BG_RAISED, fg=TEXT_PRI, selectbackground=ACCENT, relief="flat", font=f_sans)
    listbox.pack(fill="x", padx=10, pady=8)

    btn_row = tk.Frame(right_inspector, bg=BG_CARD)
    btn_row.pack(fill="x", padx=10, pady=(0, 6))

    preview_txt = tk.Text(right_inspector, bg=BG_PAGE, fg=TEXT_PRI, font=f_sans, wrap="word", relief="flat", padx=12, pady=12)
    preview_txt.pack(fill="both", expand=True, padx=10, pady=(0, 10))

    def refresh_tk_artifacts():
        listbox.delete(0, "end")
        artifact_paths.clear()
        for item in rt.list_recent_artifacts():
            listbox.insert("end", f"[{item['subsys']}] {item['name']} ({item['size_kb']} KB)")
            artifact_paths.append(item["path"])

    def on_select_artifact( _ev=None ):
        sel = listbox.curselection()
        if not sel:
            return
        p = Path(artifact_paths[sel[0]])
        selected_path_var.set(str(p))
        if p.exists():
            preview_txt.delete("1.0", "end")
            preview_txt.insert("end", p.read_text(encoding="utf-8", errors="replace")[:40000])

    listbox.bind("<<ListboxSelect>>", on_select_artifact)
    ttk.Button(btn_row, text="刷新列表", style="Action.TButton", command=refresh_tk_artifacts).pack(side="left", padx=(0, 6))
    ttk.Button(btn_row, text="定位所在目录", style="Action.TButton", command=lambda: reveal_in_explorer(Path(selected_path_var.get()), True) if selected_path_var.get() else None).pack(side="left", padx=6)
    ttk.Button(btn_row, text="打开文件", style="Action.TButton", command=lambda: open_file_default(Path(selected_path_var.get())) if selected_path_var.get() else None).pack(side="left", padx=6)

    term_text = tk.Text(term_box, bg=BG_SIDEBAR, fg=TEXT_SEC, font=f_mono, relief="flat", padx=12, pady=10)
    term_text.pack(fill="both", expand=True)

    def poll():
        while True:
            try:
                m = log_queue.get_nowait()
                term_text.insert("end", m + "\n")
                term_text.see("end")
            except queue.Empty:
                break
        root.after(100, poll)

    refresh_tk_artifacts()
    root.after(100, poll)
    root.mainloop()


# ==============================================================================
# 5. CLI 与交互终端入口
# ==============================================================================

def main_cli(argv: list[str]) -> int:
    if argv == ["--tk"]:
        launch_tk_gui()
        return 0
    if argv == ["--web"]:
        launch_unslop_web_studio()
        return 0

    rt = RuntimeEnv(ROOT_DIR)
    runner = TaskRunner(rt, log_callback=print)

    ap = argparse.ArgumentParser(
        prog="素材工具箱.exe",
        description="素材工具包 · 四合一整合程序 (download / summarize / scrape / xhs)"
    )
    ap.add_argument("--tk", action="store_true", help="使用原生 Tkinter 界面启动")
    ap.add_argument("--web", action="store_true", help="使用 Unslop Web Studio 界面启动 (默认)")
    sub = ap.add_subparsers(dest="subcmd")

    sub.add_parser("check", help="检查 README 第 3 节列出的全部 9 项外部运行时依赖")

    p_dl = sub.add_parser("download", help="子系统①：视频/音频/字幕/播放列表/抖音无水印下载")
    p_dl.add_argument("target", help="视频 URL、抖音链接 或 YouTube 搜索关键词")
    p_dl.add_argument("--mode", default="1080p", choices=["1080p", "subs_cover", "mp3", "douyin", "playlist", "yt_search", "formats"])
    p_dl.add_argument("--out", default=None, help="自定义保存目录")
    p_dl.add_argument("--cookie", default="firefox", choices=["firefox", "file", "chrome", "edge", "none"])
    p_dl.add_argument("--count", type=int, default=5)
    p_dl.add_argument("--max-minutes", type=int, default=0)
    p_dl.add_argument("--list-only", action="store_true")

    p_sum = sub.add_parser("summarize", help="子系统②：单条视频/本地文件 -> 原生字幕秒提/Whisper转写 + AI/本地摘要")
    p_sum.add_argument("target", help="视频 URL 或本地音视频文件路径")
    p_sum.add_argument("--mode", default="ai", choices=["ai", "local", "transcript_only"])
    p_sum.add_argument("--model", default="small", choices=["tiny", "base", "small", "medium"])
    p_sum.add_argument("--lang", default="zh")
    p_sum.add_argument("--out", default=None)
    p_sum.add_argument("--keep-audio", action="store_true")
    p_sum.add_argument("--force-asr", action="store_true", help="跳过自带字幕检测，强制跑 Whisper")

    p_bat = sub.add_parser("batch", help="子系统②：B站关键词 / 抖音·小红书链接列表批量转写 + AI 横向对比汇总")
    p_bat.add_argument("target", help="B站关键词 或 链接列表文件路径")
    p_bat.add_argument("--mode", default="bilibili", choices=["bilibili", "douyin_links", "xhs_links"])
    p_bat.add_argument("--count", type=int, default=3)
    p_bat.add_argument("--max-duration", type=int, default=600)
    p_bat.add_argument("--model", default="small", choices=["tiny", "base", "small", "medium"])
    p_bat.add_argument("--out", default=None)
    p_bat.add_argument("--no-transcribe", action="store_true")

    p_scp = sub.add_parser("scrape", help="子系统③：Scrapling 网页抓取转 Markdown 或 YouTube 搜索转 CSV")
    p_scp.add_argument("target", help="网页 URL 或 YouTube 搜索关键词")
    p_scp.add_argument("--mode", default="http", choices=["http", "browser", "cloudflare", "yt_csv"])
    p_scp.add_argument("--css", default="", help="CSS 选择器")
    p_scp.add_argument("--out", default=None, help="输出文件路径")

    p_xhs = sub.add_parser("xhs", help="子系统④：小红书图文原图 / 视频笔记 MP4 + 笔记.txt 下载")
    p_xhs.add_argument("url", help="小红书分享短链或 explore 链接")
    p_xhs.add_argument("--out", default=None, help="保存目录")

    sub.add_parser("pot", help="启动 YouTube PO Token 鉴权服务端 (127.0.0.1:4416)")

    args = ap.parse_args(argv)

    if args.subcmd == "check":
        print(f"=== 素材工具包 · 运行时依赖自检 (根目录: {ROOT_DIR}) ===\n")
        items = rt.inspect_all_dependencies()
        for idx, it in enumerate(items, 1):
            mark = "[OK]" if it["ok"] else "[X] "
            print(f"{idx}. {mark} {it['name']} (预期: {it['expected']}) -> {it['used_by']}")
            print(f"       路径: {it['path']}")
            print(f"       状态: {it['detail']}\n")
        return 0

    if args.subcmd == "download":
        return runner.run_download(args.mode, args.target, args.out, args.cookie, args.count, args.max_minutes, args.list_only)

    if args.subcmd == "summarize":
        return runner.run_summarize_single(args.target, args.mode, args.model, args.lang, args.out, args.keep_audio, "firefox", args.force_asr)

    if args.subcmd == "batch":
        return runner.run_summarize_batch(args.mode, args.target, args.count, args.max_duration, args.model, args.out, args.no_transcribe)

    if args.subcmd == "scrape":
        if args.mode == "yt_csv":
            rc, _ = runner.run_scrape_youtube_search(args.target, out_csv=args.out)
            return rc
        rc, _ = runner.run_scrape_page(args.target, args.mode, args.css, args.out)
        return rc

    if args.subcmd == "xhs":
        return runner.run_xhs(args.url, args.out)

    if args.subcmd == "pot":
        return 0 if rt.start_pot_server(print) else 1

    ap.print_help()
    return 0


if __name__ == "__main__":
    try:
        if len(sys.argv) > 1:
            sys.exit(main_cli(sys.argv[1:]))
        else:
            launch_unslop_web_studio()
    except Exception as exc:
        import traceback
        err_msg = traceback.format_exc()
        print(err_msg)
        if os.name == "nt":
            try:
                import ctypes
                ctypes.windll.user32.MessageBoxW(0, f"运行出错:\n{err_msg[:800]}", "素材工具箱 错误提示", 0x10)
            except Exception:
                pass
        input("按回车键退出...")
